fn run_ifp_cache_sequence(case: &CacheSequenceCase) {
    let moving = TransformedCollisionGeometry {
        source_piece_id: PieceId::new("cache-ifp-moving"),
        transform: IrregularTransformCandidate {
            index: 0.0,
            rotation_deg: 0.0,
            mirrored: false,
            reason: IrregularTransformReason::Configured,
        },
        polygon: IrregularPolygon::new(vec![
            IrregularPoint::new(0.0, 0.0),
            IrregularPoint::new(4.0, 0.0),
            IrregularPoint::new(4.0, 3.0),
            IrregularPoint::new(0.0, 3.0),
        ]),
        bounds: placeholder_bounds(),
    };
    let sheet = SheetSpec {
        width: 40.0,
        height: 30.0,
        label: "s".to_string(),
    };
    let input = ComputeIfpBoundsInput {
        sheet: &sheet,
        moving: &moving,
    };
    let mut cache = GeometryCacheStore::new();

    for (step_index, step) in case.steps.iter().enumerate() {
        assert_eq!(step.op, "compute-ifp");
        if step_index == case.steps.len() - 1 {
            let key_input = irregular_nesting_native::caches::InnerFitBoundsKeyInput {
                sheet: &sheet,
                moving: &moving,
            };
            let key = irregular_nesting_native::caches::make_inner_fit_bounds_cache_key(&key_input);
            let stale_value = irregular_nesting_native::domain::IrregularIfpBounds {
                sheet: sheet.clone(),
                moving_piece_id: PieceId::new("a-different-piece-id"),
                bounds: IrregularBounds::new(-999.0, -999.0, 999.0, 999.0),
            };
            assert!(cache.set(
                &key,
                stale_value.clone(),
                irregular_nesting_native::caches::charge_ifp_bounds(&stale_value),
            ));
        }
        let result = compute_ifp_bounds(&input, &mut cache);
        assert_eq!(step.ok, result.is_ok(), "step {step_index}: ok mismatch");
        assert_namespace_counters(
            step_index,
            &step.telemetry_after.namespace_counters,
            &cache,
            "sheet-ifp-v1",
        );
    }
}

// ---------------------------------------------------------------------------
// Sanity: total case count and section presence.
// ---------------------------------------------------------------------------

#[test]
fn vector_file_reports_at_least_500_total_cases_across_every_section() {
    let vectors = load_vectors();
    assert!(
        vectors.total_case_count >= 500,
        "expected at least 500 total nfp-ifp vectors, got {}",
        vectors.total_case_count
    );
    let summed = vectors.pairwise_nfp.case_count
        + vectors.ifp.case_count
        + vectors.candidate_alternatives.case_count
        + vectors.generated_candidates.case_count
        + vectors.rejections.case_count
        + vectors.cache_sequences.case_count;
    assert_eq!(vectors.total_case_count, summed);
}
